from pathlib import Path
import os
import shutil


def configure_v6_ann_output_root(folder_name: str = "V_6 ANN"):
    """Configure all generated outputs under Google Drive when running in Colab."""
    drive_base = Path("/content/drive/MyDrive")
    try:
        from google.colab import drive  # type: ignore
        drive.mount("/content/drive", force_remount=False)
        output_root = drive_base / folder_name
        print(f"[OK] Google Drive output root: {output_root}")
    except Exception as exc:
        output_root = Path(folder_name)
        print(f"[WARN] Google Drive is not available; using local output root: {output_root.resolve()}")
        print(f"[WARN] Drive setup detail: {exc}")

    artifact_root = output_root / "artifacts"
    artifact_root.mkdir(parents=True, exist_ok=True)
    (artifact_root / "metrics").mkdir(parents=True, exist_ok=True)
    (artifact_root / "predictions").mkdir(parents=True, exist_ok=True)
    (artifact_root / "models").mkdir(parents=True, exist_ok=True)
    (artifact_root / "plots").mkdir(parents=True, exist_ok=True)

    os.environ["V6_ANN_OUTPUT_ROOT"] = str(output_root)
    os.environ["V6_ANN_ARTIFACT_ROOT"] = str(artifact_root)
    os.environ["V6_ANN_SUMMARY_PATH"] = str(output_root / "experiments_summary.csv")

    # If a previous notebook run wrote local outputs, preserve them in the Drive folder too.
    for source, target in [
        (Path("artifacts"), artifact_root),
        (Path("configs"), output_root / "configs"),
    ]:
        try:
            if source.exists() and source.resolve() != target.resolve():
                shutil.copytree(source, target, dirs_exist_ok=True)
                print(f"[OK] Existing local folder copied to Drive output root: {target}")
        except Exception as exc:
            print(f"[WARN] Could not copy {source} to {target}: {exc}")

    summary_source = Path("experiments_summary.csv")
    summary_target = output_root / "experiments_summary.csv"
    try:
        if summary_source.exists() and summary_source.resolve() != summary_target.resolve():
            shutil.copy2(summary_source, summary_target)
            print(f"[OK] Existing experiment summary copied: {summary_target}")
    except Exception as exc:
        print(f"[WARN] Could not copy {summary_source} to {summary_target}: {exc}")

    return output_root, artifact_root, output_root / "experiments_summary.csv"


