print("\n========== MODEL INTEGRATION SMOKE TESTS ==========")

import importlib
import numpy as np

try:
    import torch
except ImportError:
    torch = None

import src.models.model_factory
import src.training.trainer
importlib.reload(src.models.model_factory)
importlib.reload(src.training.trainer)

from src.models.model_factory import build_model, get_model_family, requires_sequence_input
from src.training.trainer import run_single_torch_fold

smoke_models = [
    "xgboost",
    "lightgbm",
    "random_forest",
    "catboost",
    "lstm",
    "tcn",
    "transformer_encoder",
]

smoke_config = {
    "experiment": {"seed": 42},
    "training": {
        "batch_size": 8,
        "max_epochs": 2,
        "early_stopping_patience": 1,
        "learning_rate": 0.001,
        "learning_rate_candidates": [0.001],
    },
    "xgboost": {"n_estimators": 10, "max_depth": 2, "learning_rate": 0.1, "n_jobs": 1},
    "lightgbm": {"n_estimators": 10, "num_leaves": 7, "learning_rate": 0.1, "n_jobs": 1, "verbosity": -1},
    "random_forest": {"n_estimators": 20, "min_samples_leaf": 2, "n_jobs": 1},
    "catboost": {"iterations": 10, "depth": 2, "learning_rate": 0.1, "verbose": False, "allow_writing_files": False},
    "lstm": {"hidden_dim": 16, "num_layers": 1, "dropout": 0.1, "weighted_loss": True},
    "tcn": {"channels": [16, 16], "kernel_size": 3, "dropout": 0.1, "weighted_loss": True},
    "transformer_encoder": {"d_model": 16, "nhead": 4, "num_layers": 1, "dim_feedforward": 32, "dropout": 0.1, "weighted_loss": True},
}

rng = np.random.default_rng(42)
n_train, n_val, lookback, n_features = 32, 16, 21, 5
X_train_seq = rng.normal(size=(n_train, lookback, n_features)).astype(np.float32)
X_val_seq = rng.normal(size=(n_val, lookback, n_features)).astype(np.float32)
y_train = rng.integers(0, 2, size=n_train).astype(np.int64)
y_val = rng.integers(0, 2, size=n_val).astype(np.int64)

smoke_results = []
for model_name in smoke_models:
    try:
        family = get_model_family(model_name)
        model = build_model(model_name, smoke_config, input_shape=(lookback, n_features))

        if family == "sklearn":
            X_train_flat = X_train_seq.reshape(n_train, -1)
            X_val_flat = X_val_seq.reshape(n_val, -1)
            model.fit(X_train_flat, y_train)
            proba = model.predict_proba(X_val_flat[:4])
            if proba.shape[0] != 4:
                raise AssertionError(f"Unexpected predict_proba shape: {proba.shape}")

        elif family == "torch":
            if torch is None:
                raise ImportError("torch is required for torch model smoke tests")
            run = run_single_torch_fold(
                model=model,
                X_train=X_train_seq,
                y_train=y_train,
                X_val=X_val_seq,
                y_val=y_val,
                training_config=smoke_config["training"],
                probability_threshold=0.50,
                use_weighted_loss=bool(smoke_config.get(model_name, {}).get("weighted_loss", True)),
                device="cpu",
            )
            if "validation" not in run or "metrics" not in run["validation"]:
                raise AssertionError("Torch smoke run did not return validation metrics")
        else:
            raise AssertionError(f"Unknown family: {family}")

        smoke_results.append({"model": model_name, "status": "OK"})
        print(f"[OK] {model_name}: build + mini check passed")

    except ImportError as exc:
        smoke_results.append({"model": model_name, "status": "SKIP", "reason": str(exc)})
        print(f"[SKIP] {model_name}: {exc}")
    except Exception as exc:
        smoke_results.append({"model": model_name, "status": "FAIL", "reason": f"{type(exc).__name__}: {exc}"})
        print(f"[FAIL] {model_name}: {type(exc).__name__}: {exc}")

failed_smoke_tests = [row for row in smoke_results if row["status"] == "FAIL"]
if failed_smoke_tests:
    raise RuntimeError(f"Model smoke tests failed: {failed_smoke_tests}")

print("========== MODEL INTEGRATION SMOKE TESTS COMPLETE ==========")


