config_code = r'''
from __future__ import annotations

from pathlib import Path
from copy import deepcopy
from typing import Any, Dict, Optional

import yaml


def deep_update(base: Dict[str, Any], updates: Dict[str, Any]) -> Dict[str, Any]:
    """Recursively update nested dictionary values."""
    result = dict(base)
    for key, value in updates.items():
        if (
            key in result
            and isinstance(result[key], dict)
            and isinstance(value, dict)
        ):
            result[key] = deep_update(result[key], value)
        else:
            result[key] = value
    return result


def validate_config(config: Dict[str, Any]) -> None:
    """Validate required config keys and basic value constraints."""
    required_top_keys = [
        "experiment",
        "data",
        "split",
        "labeling",
        "sequence",
        "preprocessing",
        "decision",
        "training",
        "evaluation",
        "models",
        "artifacts",
    ]
    missing = [k for k in required_top_keys if k not in config]
    if missing:
        raise ValueError(f"Missing top-level config keys: {missing}")

    if "file_path" not in config["data"]:
        raise ValueError("config['data']['file_path'] is required.")
    if "feature_cols" not in config["data"] or not config["data"]["feature_cols"]:
        raise ValueError("config['data']['feature_cols'] must be a non-empty list.")
    if config["sequence"].get("lookback", 0) < 1:
        raise ValueError("config['sequence']['lookback'] must be >= 1.")


def load_config(config_path: str | Path, overrides: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Load YAML config and apply optional overrides."""
    config_path = Path(config_path)
    if not config_path.exists():
        raise FileNotFoundError(f"Config file not found: {config_path}")

    with open(config_path, "r", encoding="utf-8") as f:
        config = yaml.safe_load(f)

    if config is None:
        raise ValueError(f"Config file is empty: {config_path}")

    if overrides:
        config = deep_update(config, overrides)

    validate_config(config)
    return config
'''
Path("src/utils/config.py").write_text(config_code, encoding="utf-8")

