from pathlib import Path
import json
import pandas as pd
import numpy as np

# ------------------------------------------------
# 1) Select finalists dynamically from the current tuning results
# ------------------------------------------------
results_csv_path = ARTIFACT_ROOT / "metrics" / "tuning_results.csv"
metrics_dir = ARTIFACT_ROOT / "metrics"
predictions_dir = ARTIFACT_ROOT / "predictions"
max_finalists = 3

if not results_csv_path.exists():
    raise FileNotFoundError(f"Tuning results file not found: {results_csv_path}")

tuning_df = pd.read_csv(results_csv_path)
required_cols = {
    "experiment_name",
    "model_name",
    "scaler_name",
    "threshold_quantile",
    "decision_threshold",
    "test_mcc",
}
missing_cols = required_cols.difference(tuning_df.columns)
if missing_cols:
    raise ValueError(f"tuning_results.csv is missing required columns: {sorted(missing_cols)}")

ranked = tuning_df[tuning_df["test_mcc"].notna()].copy()
ranked = ranked.sort_values(["test_mcc", "cv_mcc_mean"], ascending=[False, False])

finalists = {}
for _, row in ranked.iterrows():
    exp_name = str(row["experiment_name"])
    model_name = str(row["model_name"])
    scaler_name = str(row["scaler_name"])
    model_tag = f"{model_name}_{scaler_name}"
    finalist_key = f"{exp_name}_{model_tag}"
    report_path = metrics_dir / f"{exp_name}_{model_tag}_report.json"
    preds_path = predictions_dir / f"{exp_name}_{model_tag}_test_predictions.csv"

    if not report_path.exists() or not preds_path.exists():
        print(f"[SKIP] Missing finalist artifacts for {finalist_key}")
        print(f"       report: {report_path} | exists={report_path.exists()}")
        print(f"       preds : {preds_path} | exists={preds_path.exists()}")
        continue

    finalists[finalist_key] = {
        "report": report_path,
        "preds": preds_path,
        "tuning_row": row.to_dict(),
    }

    if len(finalists) >= max_finalists:
        break

if not finalists:
    raise FileNotFoundError("No finalist report/prediction artifacts were found for the current tuning results.")

print("Selected dynamic finalists:")
for name, paths in finalists.items():
    row = paths["tuning_row"]
    print(
        f"- {name}: test_mcc={row['test_mcc']:.6f}, "
        f"q={row['threshold_quantile']}, dt={row['decision_threshold']}"
    )

# ------------------------------------------------
# 3) RaporlarÄ± ve tahminleri yÃ¼kle
# ------------------------------------------------
reports = {}
preds = {}

for name, paths in finalists.items():
    with open(paths["report"], "r", encoding="utf-8") as f:
        reports[name] = json.load(f)

    df = pd.read_csv(paths["preds"])
    preds[name] = df.copy()

print("Raporlar ve prediction dosyalarÄ± yÃ¼klendi.")

# ------------------------------------------------
# 4) Temel metrik karÅŸÄ±laÅŸtÄ±rma tablosu
# ------------------------------------------------
rows = []
for name, report in reports.items():
    metrics = report["final_test"]["metrics"]
    rows.append({
        "model_key": name,
        "model_name": report["best_cv_selection"]["model_name"],
        "scaler_name": report["best_cv_selection"]["scaler_name"],
        "cv_mcc_mean": report["best_cv_selection"]["cv_summary"]["mcc_mean"],
        "cv_mcc_std": report["best_cv_selection"]["cv_summary"]["mcc_std"],
        "test_mcc": metrics["mcc"],
        "test_balanced_accuracy": metrics["balanced_accuracy"],
        "test_f1": metrics["f1"],
        "test_accuracy": metrics["accuracy"],
        "test_precision": metrics["precision"],
        "test_recall": metrics["recall"],
        "test_roc_auc": metrics["roc_auc"],
        "confusion_matrix": str(metrics["confusion_matrix"]),
    })

summary_df = pd.DataFrame(rows).sort_values(
    by=["test_mcc", "test_balanced_accuracy"],
    ascending=[False, False]
).reset_index(drop=True)

print("\n========== FÄ°NALÄ°ST TEMEL KARÅILAÅTIRMA ==========")
print(summary_df.to_string(index=False))

# ------------------------------------------------
# 5) Prediction davranÄ±ÅŸÄ± analizi
# ------------------------------------------------
behavior_rows = []

for name, df in preds.items():
    y_true = df["y_true"].to_numpy()
    y_pred = df["y_pred"].to_numpy()
    y_prob = df["y_prob"].to_numpy()

    bull_pred_rate = float((y_pred == 1).mean())
    bear_pred_rate = float((y_pred == 0).mean())
    bull_true_rate = float((y_true == 1).mean())

    # probability daÄŸÄ±lÄ±mÄ±
    prob_q10 = float(np.quantile(y_prob, 0.10))
    prob_q25 = float(np.quantile(y_prob, 0.25))
    prob_q50 = float(np.quantile(y_prob, 0.50))
    prob_q75 = float(np.quantile(y_prob, 0.75))
    prob_q90 = float(np.quantile(y_prob, 0.90))

    behavior_rows.append({
        "model_key": name,
        "n_samples": len(df),
        "bull_true_rate": bull_true_rate,
        "bull_pred_rate": bull_pred_rate,
        "bear_pred_rate": bear_pred_rate,
        "prob_mean": float(np.mean(y_prob)),
        "prob_std": float(np.std(y_prob)),
        "prob_q10": prob_q10,
        "prob_q25": prob_q25,
        "prob_q50": prob_q50,
        "prob_q75": prob_q75,
        "prob_q90": prob_q90,
    })

behavior_df = pd.DataFrame(behavior_rows).sort_values(by="model_key").reset_index(drop=True)

print("\n========== PREDICTION DAVRANIÅI ==========")
print(behavior_df.to_string(index=False))

# ------------------------------------------------
# 6) Modeller arasÄ± tahmin uyumu
# ------------------------------------------------
model_keys = list(preds.keys())
agreement_rows = []

for i in range(len(model_keys)):
    for j in range(i + 1, len(model_keys)):
        a = model_keys[i]
        b = model_keys[j]

        df_a = preds[a].copy()
        df_b = preds[b].copy()

        merged = df_a.merge(
            df_b,
            on="timestamp",
            suffixes=("_a", "_b"),
            how="inner",
        )

        if len(merged) == 0:
            continue

        pred_agreement = float((merged["y_pred_a"] == merged["y_pred_b"]).mean())
        prob_corr = float(np.corrcoef(merged["y_prob_a"], merged["y_prob_b"])[0, 1])

        agreement_rows.append({
            "model_a": a,
            "model_b": b,
            "n_overlap": len(merged),
            "prediction_agreement": pred_agreement,
            "probability_correlation": prob_corr,
        })

agreement_df = pd.DataFrame(agreement_rows)

print("\n========== MODELLER ARASI UYUM ==========")
print(agreement_df.to_string(index=False))

# ------------------------------------------------
# 7) Hangi model neyi daha iyi yapÄ±yor? (doÄŸru tahmin analizi)
# ------------------------------------------------
correctness_frames = []

for name, df in preds.items():
    tmp = df.copy()
    tmp["is_correct"] = (tmp["y_true"] == tmp["y_pred"]).astype(int)
    tmp = tmp[["timestamp", "y_true", "y_pred", "y_prob", "is_correct"]]
    tmp = tmp.rename(columns={
        "y_pred": f"{name}_y_pred",
        "y_prob": f"{name}_y_prob",
        "is_correct": f"{name}_is_correct",
    })
    correctness_frames.append(tmp)

merged_all = correctness_frames[0]
for other in correctness_frames[1:]:
    merged_all = merged_all.merge(other, on=["timestamp", "y_true"], how="inner")

# Her Ã¶rnekte en iyi / tek doÄŸru model analizi
comparison_rows = []

for name in model_keys:
    comparison_rows.append({
        "model_key": name,
        "correct_count": int(merged_all[f"{name}_is_correct"].sum()),
    })

comparison_df = pd.DataFrame(comparison_rows).sort_values(by="correct_count", ascending=False)

print("\n========== DOÄRU TAHMÄ°N SAYISI ==========")
print(comparison_df.to_string(index=False))

# Tek baÅŸÄ±na doÄŸru olduÄŸu Ã¶rnekler
solo_rows = []
for name in model_keys:
    others = [m for m in model_keys if m != name]
    solo_mask = merged_all[f"{name}_is_correct"] == 1
    for other in others:
        solo_mask &= (merged_all[f"{other}_is_correct"] == 0)

    solo_rows.append({
        "model_key": name,
        "solo_correct_count": int(solo_mask.sum()),
    })

solo_df = pd.DataFrame(solo_rows).sort_values(by="solo_correct_count", ascending=False)

print("\n========== TEK BAÅINA DOÄRU OLDUÄU Ã–RNEK SAYISI ==========")
print(solo_df.to_string(index=False))

# ------------------------------------------------
# 8) Basit karar Ã¶nerisi
# ------------------------------------------------
best_mcc_row = summary_df.sort_values(by="test_mcc", ascending=False).iloc[0]
best_bal_acc_row = summary_df.sort_values(by="test_balanced_accuracy", ascending=False).iloc[0]

print("\n========== KARAR NOTU ==========")
print("MCC lideri        :", best_mcc_row["model_key"], "| test_mcc =", best_mcc_row["test_mcc"])
print("BalAcc lideri     :", best_bal_acc_row["model_key"], "| bal_acc  =", best_bal_acc_row["test_balanced_accuracy"])
print("En yÃ¼ksek solo hit:", solo_df.iloc[0]["model_key"], "| solo_correct_count =", solo_df.iloc[0]["solo_correct_count"])

print("\nÃ–neri:")
print("- EÄŸer ana kriter yalnÄ±zca MCC ise: MCC liderini Ã¼st tura taÅŸÄ±.")
print("- EÄŸer daha dengeli davranÄ±ÅŸ istiyorsan: MCC + Balanced Accuracy birlikte deÄŸerlendir.")
print("- EÄŸer ensemble dÃ¼ÅŸÃ¼neceksen: prediction_agreement dÃ¼ÅŸÃ¼k olan Ã§iftler daha ilginÃ§ olabilir.")

# ------------------------------------------------
# 9) SonuÃ§larÄ± kaydet
# ------------------------------------------------
out_dir = ARTIFACT_ROOT / "metrics"
out_dir.mkdir(parents=True, exist_ok=True)

summary_df.to_csv(out_dir / "finalist_summary_metrics.csv", index=False)
behavior_df.to_csv(out_dir / "finalist_behavior_metrics.csv", index=False)
agreement_df.to_csv(out_dir / "finalist_pairwise_agreement.csv", index=False)
comparison_df.to_csv(out_dir / "finalist_correct_count.csv", index=False)
solo_df.to_csv(out_dir / "finalist_solo_correct_count.csv", index=False)

print("\nKaydedilen dosyalar:")
print("-", out_dir / "finalist_summary_metrics.csv")
print("-", out_dir / "finalist_behavior_metrics.csv")
print("-", out_dir / "finalist_pairwise_agreement.csv")
print("-", out_dir / "finalist_correct_count.csv")
print("-", out_dir / "finalist_solo_correct_count.csv")

