from pathlib import Path

script = r'''
from pathlib import Path
import os
import json
import ast
import re

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt


OUTPUT_ROOT = Path(os.environ.get("V6_ANN_OUTPUT_ROOT", "V_6 ANN"))
ARTIFACT_ROOT = Path(os.environ.get("V6_ANN_ARTIFACT_ROOT", str(OUTPUT_ROOT / "artifacts")))
SUMMARY_PATH = Path(os.environ.get("V6_ANN_SUMMARY_PATH", str(OUTPUT_ROOT / "experiments_summary.csv")))
ROOT = OUTPUT_ROOT
OUT_DIR = ARTIFACT_ROOT / "plots" / "report_extra"
OUT_DIR.mkdir(parents=True, exist_ok=True)

FINAL_REPORT = ARTIFACT_ROOT / "metrics" / "FINAL_SELECTED_MODEL_REPORT.json"
SECONDARY_REPORT = ARTIFACT_ROOT / "metrics" / "SECONDARY_CANDIDATE_REPORT.json"
FINAL_PREDS = ARTIFACT_ROOT / "predictions" / "FINAL_SELECTED_MODEL_PREDICTIONS.csv"
SECONDARY_PREDS = ARTIFACT_ROOT / "predictions" / "SECONDARY_CANDIDATE_PREDICTIONS.csv"

FAIR_Q50 = ARTIFACT_ROOT / "metrics" / "fair_finalist_comparison.csv"
FAIR_Q40 = ARTIFACT_ROOT / "metrics" / "fair_finalist_comparison_q40.csv"
FINAL_WINNER = ARTIFACT_ROOT / "metrics" / "final_winner_selection.csv"
TUNING_RESULTS = ARTIFACT_ROOT / "metrics" / "tuning_results.csv"


def save_fig(name: str):
    out = OUT_DIR / name
    plt.tight_layout()
    plt.savefig(out, dpi=180, bbox_inches="tight")
    plt.close()
    print(f"[OK] Saved: {out}")


def safe_read_csv(path: Path):
    if not path.exists():
        print(f"[SKIP] Missing file: {path}")
        return None
    return pd.read_csv(path)


def safe_read_json(path: Path):
    if not path.exists():
        print(f"[SKIP] Missing file: {path}")
        return None
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def sanitize_filename(value: str) -> str:
    value = str(value).strip()
    value = re.sub(r"[^A-Za-z0-9_.-]+", "_", value)
    return value.strip("_") or "loss_curve"


def extract_loss_history(history):
    if not history:
        return pd.DataFrame()

    df = pd.DataFrame(history)
    if "epoch" not in df.columns and "iteration" in df.columns:
        df["epoch"] = df["iteration"]
    if "epoch" not in df.columns:
        return pd.DataFrame()
    if "train_loss" not in df.columns:
        df["train_loss"] = np.nan
    if "val_loss" not in df.columns:
        df["val_loss"] = np.nan

    df = df[["epoch", "train_loss", "val_loss"]].copy()
    for col in ["epoch", "train_loss", "val_loss"]:
        df[col] = pd.to_numeric(df[col], errors="coerce")
    df = df.dropna(subset=["epoch"])
    df = df[~(df["train_loss"].isna() & df["val_loss"].isna())]
    return df.sort_values("epoch")


def extract_fold_items(data):
    if isinstance(data, list):
        return [item for item in data if isinstance(item, dict)]
    if isinstance(data, dict):
        for key in ["fold_results", "folds", "results"]:
            value = data.get(key)
            if isinstance(value, list):
                return [item for item in value if isinstance(item, dict)]
        if all(isinstance(value, dict) for value in data.values()):
            return list(data.values())
    return []


def annotate_bars(ax, fmt="{:.3f}"):
    for p in ax.patches:
        height = p.get_height()
        if pd.notna(height):
            ax.annotate(
                fmt.format(height),
                (p.get_x() + p.get_width() / 2., height),
                ha="center",
                va="bottom",
                fontsize=8,
                xytext=(0, 3),
                textcoords="offset points"
            )


# ------------------------------------------------
# 1) Final winner vs secondary: CV MCC vs Test MCC
# ------------------------------------------------
def plot_cv_vs_test_mcc():
    final_report = safe_read_json(FINAL_REPORT)
    secondary_report = safe_read_json(SECONDARY_REPORT)
    if final_report is None or secondary_report is None:
        return

    rows = [
        {
            "label": "final_logreg_robust",
            "cv_mcc_mean": final_report["best_cv_selection"]["cv_summary"]["mcc_mean"],
            "test_mcc": final_report["final_test"]["metrics"]["mcc"],
        },
        {
            "label": "secondary_cnn1d_standard",
            "cv_mcc_mean": secondary_report["best_cv_selection"]["cv_summary"]["mcc_mean"],
            "test_mcc": secondary_report["final_test"]["metrics"]["mcc"],
        },
    ]
    df = pd.DataFrame(rows)

    x = np.arange(len(df))
    width = 0.35

    plt.figure(figsize=(10, 5))
    ax = plt.gca()
    ax.bar(x - width / 2, df["cv_mcc_mean"], width, label="CV MCC Mean")
    ax.bar(x + width / 2, df["test_mcc"], width, label="Test MCC")
    ax.set_xticks(x)
    ax.set_xticklabels(df["label"], rotation=15)
    ax.set_ylabel("MCC")
    ax.set_title("Final Winner vs Secondary - CV MCC Mean / Test MCC")
    ax.legend()

    save_fig("01_cv_vs_test_mcc.png")


# ------------------------------------------------
# 2) Confusion matrix plots
# ------------------------------------------------
def plot_confusion_matrices():
    final_report = safe_read_json(FINAL_REPORT)
    secondary_report = safe_read_json(SECONDARY_REPORT)
    if final_report is None or secondary_report is None:
        return

    items = [
        ("final_logreg_robust", final_report["final_test"]["metrics"]["confusion_matrix"]),
        ("secondary_cnn1d_standard", secondary_report["final_test"]["metrics"]["confusion_matrix"]),
    ]

    fig, axes = plt.subplots(1, 2, figsize=(10, 4.5))
    if len(items) == 1:
        axes = [axes]

    for ax, (title, cm) in zip(axes, items):
        cm = np.array(cm)
        im = ax.imshow(cm, aspect="auto")
        ax.set_title(title)
        ax.set_xlabel("Predicted")
        ax.set_ylabel("True")
        ax.set_xticks([0, 1])
        ax.set_yticks([0, 1])
        ax.set_xticklabels(["bear", "bull"])
        ax.set_yticklabels(["bear", "bull"])

        for i in range(cm.shape[0]):
            for j in range(cm.shape[1]):
                ax.text(j, i, str(cm[i, j]), ha="center", va="center", fontsize=11)

        plt.colorbar(im, ax=ax)

    save_fig("02_confusion_matrices_final_vs_secondary.png")


# ------------------------------------------------
# 3) True class rate vs prediction rate
# ------------------------------------------------
def plot_class_distribution_vs_predictions():
    final_preds = safe_read_csv(FINAL_PREDS)
    secondary_preds = safe_read_csv(SECONDARY_PREDS)
    if final_preds is None or secondary_preds is None:
        return

    def make_rows(df, label):
        return {
            "label": label,
            "true_bull_rate": float((df["y_true"] == 1).mean()),
            "pred_bull_rate": float((df["y_pred"] == 1).mean()),
            "true_bear_rate": float((df["y_true"] == 0).mean()),
            "pred_bear_rate": float((df["y_pred"] == 0).mean()),
        }

    rows = [
        make_rows(final_preds, "final_logreg_robust"),
        make_rows(secondary_preds, "secondary_cnn1d_standard"),
    ]
    df = pd.DataFrame(rows)

    x = np.arange(len(df))
    width = 0.2

    plt.figure(figsize=(12, 5))
    ax = plt.gca()
    ax.bar(x - 1.5 * width, df["true_bull_rate"], width, label="true bull rate")
    ax.bar(x - 0.5 * width, df["pred_bull_rate"], width, label="pred bull rate")
    ax.bar(x + 0.5 * width, df["true_bear_rate"], width, label="true bear rate")
    ax.bar(x + 1.5 * width, df["pred_bear_rate"], width, label="pred bear rate")
    ax.set_xticks(x)
    ax.set_xticklabels(df["label"], rotation=15)
    ax.set_ylim(0, 1)
    ax.set_ylabel("Rate")
    ax.set_title("True Class Rate vs Model Prediction Rate")
    ax.legend()

    save_fig("03_true_vs_pred_class_rates.png")


# ------------------------------------------------
# 4) Probability histogram
# ------------------------------------------------
def plot_probability_histograms():
    final_preds = safe_read_csv(FINAL_PREDS)
    secondary_preds = safe_read_csv(SECONDARY_PREDS)
    if final_preds is None or secondary_preds is None:
        return

    fig, axes = plt.subplots(1, 2, figsize=(12, 4.5))

    axes[0].hist(final_preds["y_prob"], bins=20)
    axes[0].set_title("Final Winner - Probability Histogram")
    axes[0].set_xlabel("P(bull)")
    axes[0].set_ylabel("Count")

    axes[1].hist(secondary_preds["y_prob"], bins=20)
    axes[1].set_title("Secondary Candidate - Probability Histogram")
    axes[1].set_xlabel("P(bull)")
    axes[1].set_ylabel("Count")

    save_fig("04_probability_histograms.png")


# ------------------------------------------------
# 5) Threshold sensitivity (from tuning_results)
#    decision threshold -> test_mcc by model + scaler
# ------------------------------------------------
def plot_threshold_sensitivity():
    df = safe_read_csv(TUNING_RESULTS)
    if df is None or df.empty:
        return

    ok = df[df["test_mcc"].notna()].copy()
    if ok.empty:
        return

    combos = [
        ("cnn1d", "standard"),
        ("cnn1d", "robust"),
        ("logreg", "robust"),
        ("logreg", "standard"),
    ]

    fig, axes = plt.subplots(2, 2, figsize=(12, 8))
    axes = axes.flatten()

    for ax, (model_name, scaler_name) in zip(axes, combos):
        sub = ok[(ok["model_name"] == model_name) & (ok["scaler_name"] == scaler_name)].copy()
        if sub.empty:
            ax.set_title(f"{model_name}/{scaler_name} - no data")
            ax.axis("off")
            continue

        for q, qsub in sub.groupby("threshold_quantile"):
            grp = qsub.groupby("decision_threshold", as_index=False)["test_mcc"].max().sort_values("decision_threshold")
            ax.plot(grp["decision_threshold"], grp["test_mcc"], marker="o", label=f"q={q:.2f}")

        ax.set_title(f"{model_name} / {scaler_name}")
        ax.set_xlabel("Decision Threshold")
        ax.set_ylabel("Test MCC")
        ax.legend()

    save_fig("05_threshold_sensitivity.png")


# ------------------------------------------------
# 6) Q40 / Q50 finalist decision-threshold curves
# ------------------------------------------------
def plot_fair_regime_threshold_curves():
    q40 = safe_read_csv(FAIR_Q40)
    q50 = safe_read_csv(FAIR_Q50)
    if q40 is None or q50 is None:
        return

    q40 = q40[q40["test_mcc"].notna()].copy()
    q50 = q50[q50["test_mcc"].notna()].copy()

    fig, axes = plt.subplots(1, 2, figsize=(12, 4.5))

    for regime_df, regime_name, ax in [(q40, "Q40", axes[0]), (q50, "Q50", axes[1])]:
        for tag, sub in regime_df.groupby("model_tag"):
            grp = sub.groupby("decision_threshold", as_index=False)["test_mcc"].max().sort_values("decision_threshold")
            ax.plot(grp["decision_threshold"], grp["test_mcc"], marker="o", label=tag)

        ax.set_title(f"{regime_name} - Decision Threshold vs Test MCC")
        ax.set_xlabel("Decision Threshold")
        ax.set_ylabel("Test MCC")
        ax.legend()

    save_fig("06_fair_regime_threshold_curves.png")


# ------------------------------------------------
# 7) Final winner selection multi-bar summary
# ------------------------------------------------
def plot_training_validation_loss_curves():
    any_plot = False

    for folds_path in sorted((ARTIFACT_ROOT / "metrics").glob("*_folds.json")):
        data = safe_read_json(folds_path)
        if not data:
            continue

        for fold in extract_fold_items(data):
            history = fold.get("trainer_info", {}).get("history", [])
            df = extract_loss_history(history)
            if df.empty:
                continue

            label = "_".join([
                str(fold.get("model_name", "model")),
                str(fold.get("scaler_name", "scaler")),
                f"fold{fold.get('fold_index', 'x')}",
            ])
            plt.figure(figsize=(8, 4.5))
            ax = plt.gca()
            ax.plot(df["epoch"], df["train_loss"], marker="o", label="Train loss")
            ax.plot(df["epoch"], df["val_loss"], marker="o", label="Validation loss")
            ax.set_title(f"Training vs Validation Loss - {label}")
            ax.set_xlabel("Epoch")
            ax.set_ylabel("Loss")
            ax.legend()
            save_fig(f"08_loss_{sanitize_filename(label)}.png")
            any_plot = True

    for report_path in sorted((ARTIFACT_ROOT / "metrics").glob("*_report.json")):
        report = safe_read_json(report_path)
        if not report:
            continue

        final_test = report.get("final_test", {})
        history = final_test.get("final_train_info", {}).get("history", [])
        df = extract_loss_history(history)
        if df.empty:
            continue

        label = "_".join([
            str(report.get("experiment_name", report_path.stem)),
            str(final_test.get("model_name", "final")),
            str(final_test.get("scaler_name", "scaler")),
            "final_train",
        ])
        plt.figure(figsize=(8, 4.5))
        ax = plt.gca()
        ax.plot(df["epoch"], df["train_loss"], marker="o", label="Train loss")
        ax.plot(df["epoch"], df["val_loss"], marker="o", label="Validation loss")
        ax.set_title(f"Final Training vs Validation Loss - {label}")
        ax.set_xlabel("Epoch")
        ax.set_ylabel("Loss")
        ax.legend()
        save_fig(f"08_loss_{sanitize_filename(label)}.png")
        any_plot = True

    if not any_plot:
        print("[SKIP] No loss history found. Loss plots will be generated after retraining Torch models.")


def mcc_score_np(y_true, y_pred):
    y_true = np.asarray(y_true).astype(int)
    y_pred = np.asarray(y_pred).astype(int)
    tp = float(((y_true == 1) & (y_pred == 1)).sum())
    tn = float(((y_true == 0) & (y_pred == 0)).sum())
    fp = float(((y_true == 0) & (y_pred == 1)).sum())
    fn = float(((y_true == 1) & (y_pred == 0)).sum())
    denom = np.sqrt((tp + fp) * (tp + fn) * (tn + fp) * (tn + fn))
    if denom == 0:
        return 0.0
    return float(((tp * tn) - (fp * fn)) / denom)


def confusion_matrix_counts(y_true, y_pred):
    y_true = np.asarray(y_true).astype(int)
    y_pred = np.asarray(y_pred).astype(int)
    return np.array([
        [int(((y_true == 0) & (y_pred == 0)).sum()), int(((y_true == 0) & (y_pred == 1)).sum())],
        [int(((y_true == 1) & (y_pred == 0)).sum()), int(((y_true == 1) & (y_pred == 1)).sum())],
    ])


def get_best_tuning_rows_per_model():
    df = safe_read_csv(TUNING_RESULTS)
    if df is None or df.empty:
        return pd.DataFrame()
    needed = {"experiment_name", "model_name", "scaler_name", "decision_threshold", "test_mcc"}
    if not needed.issubset(df.columns):
        print(f"[SKIP] tuning_results.csv missing columns for diagnostics: {sorted(needed.difference(df.columns))}")
        return pd.DataFrame()
    ok = df[df["test_mcc"].notna()].copy()
    if ok.empty:
        return pd.DataFrame()
    sort_cols = ["model_name", "test_mcc"]
    ascending = [True, False]
    if "cv_mcc_mean" in ok.columns:
        sort_cols.append("cv_mcc_mean")
        ascending.append(False)
    ok = ok.sort_values(sort_cols, ascending=ascending)
    return ok.groupby("model_name", as_index=False).first()


def prediction_path_for_tuning_row(row):
    exp_name = str(row["experiment_name"])
    model_tag = f"{row['model_name']}_{row['scaler_name']}"
    return ARTIFACT_ROOT / "predictions" / f"{exp_name}_{model_tag}_test_predictions.csv"


def plot_best_model_diagnostics():
    best_rows = get_best_tuning_rows_per_model()
    if best_rows.empty:
        print("[SKIP] No tuning rows available for best-model diagnostics.")
        return

    thresholds = np.round(np.arange(0.05, 0.951, 0.01), 2)

    for _, row in best_rows.iterrows():
        pred_path = prediction_path_for_tuning_row(row)
        if not pred_path.exists():
            print(f"[SKIP] Prediction file not found for diagnostics: {pred_path}")
            continue

        preds = pd.read_csv(pred_path)
        if not {"y_true", "y_prob", "y_pred"}.issubset(preds.columns):
            print(f"[SKIP] Prediction file missing y_true/y_prob/y_pred: {pred_path}")
            continue

        y_true = preds["y_true"].to_numpy().astype(int)
        y_prob = preds["y_prob"].to_numpy().astype(float)
        tuned_threshold = float(row.get("decision_threshold", 0.50))
        tuned_pred = (y_prob >= tuned_threshold).astype(int)

        threshold_mcc = [mcc_score_np(y_true, (y_prob >= thr).astype(int)) for thr in thresholds]
        best_idx = int(np.argmax(threshold_mcc))
        best_thr = float(thresholds[best_idx])
        best_mcc = float(threshold_mcc[best_idx])

        bins = np.linspace(0, 1, 11)
        bin_centers = []
        true_rates = []
        counts = []
        for lo, hi in zip(bins[:-1], bins[1:]):
            if hi == 1:
                mask = (y_prob >= lo) & (y_prob <= hi)
            else:
                mask = (y_prob >= lo) & (y_prob < hi)
            if mask.any():
                bin_centers.append(float(y_prob[mask].mean()))
                true_rates.append(float(y_true[mask].mean()))
                counts.append(int(mask.sum()))

        cm = confusion_matrix_counts(y_true, tuned_pred)
        label = f"{row['model_name']}_{row['scaler_name']}_q{int(float(row.get('threshold_quantile', 0)) * 100):02d}_dt{int(tuned_threshold * 100):02d}"

        fig, axes = plt.subplots(2, 2, figsize=(12, 9))
        axes = axes.flatten()

        axes[0].plot(thresholds, threshold_mcc, marker="o", markersize=3)
        axes[0].axvline(tuned_threshold, linestyle="--", label=f"selected={tuned_threshold:.2f}")
        axes[0].axvline(best_thr, linestyle=":", label=f"best={best_thr:.2f}")
        axes[0].set_title(f"Threshold vs MCC - {label}")
        axes[0].set_xlabel("Decision threshold")
        axes[0].set_ylabel("MCC")
        axes[0].legend()
        axes[0].text(0.05, 0.95, f"best MCC={best_mcc:.3f}", transform=axes[0].transAxes, va="top")

        axes[1].plot([0, 1], [0, 1], linestyle="--")
        axes[1].scatter(bin_centers, true_rates, s=[max(20, c * 2) for c in counts] if counts else 20)
        axes[1].set_xlim(0, 1)
        axes[1].set_ylim(0, 1)
        axes[1].set_title(f"Calibration - {label}")
        axes[1].set_xlabel("Mean predicted probability")
        axes[1].set_ylabel("Observed bull rate")

        axes[2].hist(y_prob, bins=20)
        axes[2].axvline(tuned_threshold, linestyle="--")
        axes[2].set_title(f"Probability Histogram - {label}")
        axes[2].set_xlabel("P(bull)")
        axes[2].set_ylabel("Count")

        im = axes[3].imshow(cm, aspect="auto")
        axes[3].set_title(f"Confusion Matrix - {label}")
        axes[3].set_xlabel("Predicted")
        axes[3].set_ylabel("True")
        axes[3].set_xticks([0, 1])
        axes[3].set_yticks([0, 1])
        axes[3].set_xticklabels(["bear", "bull"])
        axes[3].set_yticklabels(["bear", "bull"])
        for i in range(cm.shape[0]):
            for j in range(cm.shape[1]):
                axes[3].text(j, i, str(cm[i, j]), ha="center", va="center", fontsize=11)
        plt.colorbar(im, ax=axes[3])

        save_fig(f"09_best_model_diagnostics_{sanitize_filename(label)}.png")

def plot_final_selection_metrics():
    df = safe_read_csv(FINAL_WINNER)
    if df is None or df.empty:
        return

    metrics = [
        "mean_test_mcc",
        "mean_test_balanced_accuracy",
        "mean_cv_mcc_mean",
    ]

    fig, axes = plt.subplots(1, 3, figsize=(16, 4.5))
    for ax, m in zip(axes, metrics):
        df.plot.bar(x="model_tag", y=m, ax=ax, legend=False)
        ax.set_title(m)
        ax.tick_params(axis="x", rotation=20)
        annotate_bars(ax)

    save_fig("07_final_selection_metrics.png")


if __name__ == "__main__":
    plot_cv_vs_test_mcc()
    plot_confusion_matrices()
    plot_class_distribution_vs_predictions()
    plot_probability_histograms()
    plot_threshold_sensitivity()
    plot_fair_regime_threshold_curves()
    plot_training_validation_loss_curves()
    plot_best_model_diagnostics()
    plot_final_selection_metrics()

    print("\\nExtra report plots were generated.")
    print("Folder:", OUT_DIR)
'''

Path("report_plots_extra.py").write_text(script, encoding="utf-8")
print("Written: report_plots_extra.py")

